from modele import *

notes=tableau(['Note','$6$','$8$','$10$','$12$','$16$'],[['Effectif','$2$','$3$','$6$','$5$','$4$']])
chapitre(10,'statistiques','Statistiques et représentations','3 · Données et hasard',
'Effectifs · Fréquences · Moyenne · Médiane · Étendue',
['Organiser et représenter une série.','Calculer et interpréter des indicateurs.','Comparer sans confondre moyenne et dispersion.'],['Fractions et pourcentages.'],[
r'''\essSection{1}{Décrire une série}
\begin{definition}L’effectif total est le nombre d’observations. La fréquence d’une valeur est son effectif divisé par l’effectif total. La somme des fréquences vaut 1, soit 100 \%.\end{definition}
\begin{propriete}La moyenne est la somme des valeurs divisée par leur nombre. Avec un tableau, multiplier chaque valeur par son effectif, additionner les produits puis diviser par l’effectif total.\end{propriete}
\begin{definition}Une médiane partage une série ordonnée en deux groupes : au moins la moitié des valeurs sont inférieures ou égales à elle et au moins la moitié sont supérieures ou égales à elle. Pour un effectif pair, ce livre retient la moyenne des deux valeurs centrales.\end{definition}
\begin{definition}L’étendue est la différence entre la plus grande et la plus petite valeur. Elle mesure une dispersion, sans décrire la répartition entre les extrêmes.\end{definition}
\begin{exemple}Pour $2;3;3;8$, la moyenne vaut 4, la médiane vaut 3 et l’étendue vaut 6. Ces trois nombres répondent à des questions différentes.\end{exemple}''',
r'''\essSection{2}{Choisir et lire un graphique}
\begin{savoirfaire}[Représenter]Un diagramme en bâtons convient à des valeurs distinctes ; un diagramme circulaire partage un total, avec un angle égal à $360^\circ$ multiplié par la fréquence. Un histogramme représente des données regroupées en classes.\end{savoirfaire}
\begin{propriete}Dans les histogrammes de ce chapitre, les classes ont la même largeur. Les hauteurs peuvent donc représenter directement leurs effectifs. Les rectangles sont accolés. Une classe $[10;20[$ contient 10 et exclut 20.\end{propriete}
\begin{attention}Un regroupement en classes fait perdre les valeurs exactes. On peut repérer une classe contenant la médiane, mais pas forcément la médiane exacte. Les centres de classes donnent seulement une estimation de la moyenne.\end{attention}
\begin{savoirfaire}[Comparer]Préciser les unités, la taille des groupes, les axes et leur origine. Une moyenne identique n’impose ni une médiane identique ni une même dispersion. Une observation extrême peut déplacer fortement la moyenne.\end{savoirfaire}'''],[
E('Compter',r"Pour la série $2;4;4;5;7;8$, donner l’effectif total et l’effectif de 4.",r"On compte $\res6$ observations ; 4 apparaît $\res2$ fois. Les répétitions comptent comme des observations distinctes.","Compter les observations, pas seulement les valeurs différentes.","assert len([2,4,4,5,7,8])==6 and [2,4,4,5,7,8].count(4)==2"),
E('Une fréquence',r"Dans un groupe de 30 élèves, 12 viennent à vélo. Donner la fréquence et le pourcentage correspondants.",r"La fréquence est $12/30=\res{0{,}4}$, soit $\res{40\,\%}$. Le dénominateur est l’effectif de tout le groupe.","Identifier le total de référence.","assert Rational(12,30)==Rational('.4')"),
E('Une moyenne simple',r"Calculer la moyenne de $7;9;10;14$.",r"La somme vaut 40. La moyenne vaut $40/4=\res{10}$. Elle n’est pas nécessairement l’une des valeurs, même si c’est le cas ici.","Additionner puis diviser par l’effectif.","assert sum([7,9,10,14])/4==10"),
E('Ordonner avant la médiane',r"Déterminer la médiane de $13;4;9;7;11$.",r"La liste ordonnée est $4;7;9;11;13$. La troisième des cinq valeurs est $\res9$. Deux valeurs sont de chaque côté.","Ranger avant de choisir le rang central.","assert sorted([13,4,9,7,11])[2]==9"),
E('Mesurer l’étendue',r"Les températures relevées sont $-3;2;5;-1;8$ degrés Celsius. Donner l’étendue.",r"Le maximum est 8 et le minimum $-3$. L’étendue vaut $8-(-3)=\res{11\,^\circ\mathrm C}$. Elle est positive.","Soustraire le minimum, même s’il est négatif.","assert 8-(-3)==11"),
E('Un tableau complet',r"Calculer l’effectif, la moyenne, la médiane et l’étendue des notes."+notes,r"L’effectif est $2+3+6+5+4=20$. La somme pondérée vaut $12+24+60+60+64=220$, d’où une moyenne de $\res{11}$. Les rangs 10 et 11 portent tous deux 10 : médiane $\res{10}$. L’étendue vaut $16-6=\res{10}$.","Utiliser les effectifs cumulés pour les rangs centraux.","v=[6]*2+[8]*3+[10]*6+[12]*5+[16]*4; assert len(v)==20 and sum(v)==220 and v[9]==v[10]==10 and max(v)-min(v)==10"),
E('Une médiane paire',r"Pour $1;3;6;8;10;20$, donner la médiane retenue dans ce livre et la moyenne.",r"Les deux valeurs centrales sont 6 et 8. La médiane retenue est $(6+8)/2=\res7$. La moyenne vaut $48/6=\res8$. La valeur 20 tire la moyenne vers le haut.","Distinguer un rang d’une valeur.","assert (6+8)/2==7 and sum([1,3,6,8,10,20])/6==8"),
E('Un disque statistique',r"Sur 40 réponses : 10 choisissent A, 18 choisissent B et 12 choisissent C. Calculer les angles du diagramme circulaire.",r"Chaque réponse représente $360/40=9^\circ$. Les angles sont $\res{90^\circ}$, $\res{162^\circ}$ et $\res{108^\circ}$. Leur somme est 360 degrés.","Multiplier les fréquences par un tour complet.","assert [a*9 for a in [10,18,12]]==[90,162,108] and sum([90,162,108])==360",figure='stat-disque'),
E('Un histogramme',r"Les durées sont regroupées en classes de 10 minutes : $[0;10[$, $[10;20[$, $[20;30[$, $[30;40[$. Lire les effectifs sur la figure et la classe contenant les deux rangs centraux.",r"Les effectifs sont 4, 8, 6 et 2 : total $\res{20}$. Les rangs 10 et 11 sont dans la deuxième classe, donc la médiane est dans $\res{[10;20[}$. La figure ne permet pas sa valeur exacte.","Cumuler les effectifs et tenir compte du regroupement.","assert sum([4,8,6,2])==20 and 4<10<=12 and 4<11<=12",figure='stat-histogramme'),
E('Une formule de tableur',r"Les valeurs 4, 7, 12 sont en A2:A4 et leurs effectifs 3, 5, 2 en B2:B4. Écrire une formule donnant la somme pondérée puis la moyenne.",r"On peut saisir =A2*B2+A3*B3+A4*B4, puis diviser par SOMME(B2:B4). La somme pondérée vaut $12+35+24=71$ ; la moyenne vaut $\res{7{,}1}$. MOYENNE(A2:A4) ignorerait les effectifs.","Pondérer avant de diviser.","assert Rational(4*3+7*5+12*2,3+5+2)==Rational('7.1')"),
E('Réunir deux groupes',r"Un groupe de 12 élèves a une moyenne de 13 ; un autre de 18 élèves a une moyenne de 11. Quelle est la moyenne des 30 élèves ?",r"Les sommes valent $12\times13=156$ et $18\times11=198$. La moyenne commune vaut $(156+198)/30=\res{11{,}8}$. Faire $(13+11)/2$ donnerait un poids égal à des groupes de tailles différentes.","Reconstituer les sommes de chaque groupe.","assert Rational(12*13+18*11,30)==Rational('11.8')"),
E('Une note manquante',r"Quatre notes sont 8, 12, 14 et $x$. Leur moyenne est 12,5. Déterminer $x$.",r"La somme des quatre notes vaut $4\times12{,}5=50$. Les trois connues totalisent 34 ; $\res{x=16}$. Le contrôle donne bien $50/4=12{,}5$.","Traduire la moyenne en somme.","assert 4*Rational('12.5')-8-12-14==16"),
E('Même moyenne, mêmes résultats ?',r"Comparer les séries A : $9;10;10;11$ et B : $2;10;10;18$. Calculer moyenne, médiane et étendue, puis commenter.",r"Les deux sommes valent 40 : les moyennes sont 10. Les deux médianes sont 10. Les étendues sont $\res2$ et $\res{16}$. B est beaucoup plus dispersée selon l’étendue ; les seuls indicateurs centraux masquent cet écart.","Comparer un indicateur de position et un de dispersion.","assert sum([9,10,10,11])==sum([2,10,10,18])==40 and 11-9==2 and 18-2==16"),
E('Ajouter une observation',r"Une série de 9 valeurs a une moyenne de 14. On ajoute 24. Calculer la nouvelle moyenne. Peut-on en déduire la nouvelle médiane ?",r"L’ancienne somme est 126 ; la nouvelle vaut 150 pour 10 valeurs. La moyenne est $\res{15}$. La médiane reste inconnue : la somme ne renseigne pas sur les valeurs centrales. Par exemple neuf 14 et la série huit 13 plus 22 ont la même moyenne initiale mais des médianes différentes après l’ajout.","Séparer ce que détermine la somme de ce qui demande l’ordre.","assert (9*14+24)/10==15 and 8*13+22==126"),
E('Un graphique trompeur',r"Deux barres représentent 80 et 84 inscriptions. Un axe vertical commence à 78. Comparer la hausse réelle et les hauteurs visibles à partir de 78.",r"La hausse réelle est $(84-80)/80=\res{5\,\%}$. Les hauteurs visibles sont 2 et 6, dans un rapport 3. Ce rapport visuel ne traduit pas un triplement des inscriptions. Lire l’origine et les graduations avant de comparer.","Ramener le pourcentage à la valeur initiale.","assert Rational(84-80,80)==Rational(5,100) and Rational(84-78,80-78)==3",figure='stat-axe-tronque')
],reperes=['Effectifs et fréquences','Moyennes simples et pondérées','Médiane et étendue','Diagrammes et histogrammes de même amplitude'])

chapitre(11,'probabilites','Probabilités et expériences à deux étapes','3 · Données et hasard',
'Issues · Événements · Tableaux · Arbres · Fréquences',
['Calculer dans une situation d’équiprobabilité.','Énumérer les issues d’une expérience à deux étapes.','Distinguer probabilité et fréquence observée.'],['Fractions et proportionnalité.'],[
r'''\essSection{1}{Modéliser le hasard}
\begin{definition}Une issue est un résultat possible. Un événement est un ensemble d’issues. Sa probabilité est comprise entre 0 et 1. Un événement impossible a pour probabilité 0 ; l’événement certain a pour probabilité 1.\end{definition}
\begin{propriete}Si toutes les issues sont équiprobables, la probabilité d’un événement vaut le nombre d’issues favorables divisé par le nombre total d’issues. Justifier cette équiprobabilité : un dé équilibré, des boules indiscernables au toucher, un choix uniforme.\end{propriete}
\begin{propriete}L’événement contraire de A contient les issues qui ne réalisent pas A. Sa probabilité est $1-P(A)$. Si deux événements ne peuvent se produire ensemble, la probabilité de leur réunion est la somme de leurs probabilités.\end{propriete}
\begin{attention}Compter des noms de couleurs n’est pas compter des issues équiprobables si les couleurs n’ont pas les mêmes effectifs. « Au moins un » inclut un ou plusieurs.\end{attention}''',
r'''\essSection{2}{Deux étapes et simulations}
\begin{savoirfaire}[Énumérer]Un tableau à double entrée ou un arbre permet de ne rien oublier. Une feuille de l’arbre représente une succession ordonnée d’issues. Les branches issues d’un même nœud décrivent toutes les possibilités à cette étape.\end{savoirfaire}
\begin{exemple}Deux pièces équilibrées lancées indépendamment donnent quatre issues équiprobables : PP, PF, FP, FF. L’événement « exactement une face F » contient PF et FP, donc a pour probabilité $2/4=1/2$.\end{exemple}
\begin{savoirfaire}[Utiliser des poids]Pour les expériences décrites ici, multiplier les probabilités successives le long d’un chemin, puis additionner les chemins favorables. Sans remise, les nombres de boules et le total changent après le premier tirage. L’arbre explicite ce changement, sans formalisme de probabilité conditionnelle.\end{savoirfaire}
\begin{propriete}La fréquence observée est le nombre de succès divisé par le nombre d’essais. Pour beaucoup de répétitions dans les mêmes conditions, elle tend généralement à se stabiliser près de la probabilité. Cela ne prédit ni le prochain résultat ni une égalité exacte pour un nombre fini d’essais.\end{propriete}'''],[
E('Un dé',r"On lance un dé équilibré à six faces numérotées de 1 à 6. Quelle est la probabilité d’obtenir un nombre pair ?",r"Les issues favorables sont 2, 4 et 6, parmi six issues équiprobables. La probabilité vaut $3/6=\res{1/2}$.","Énumérer les issues favorables.","assert Rational(len([a for a in range(1,7) if a%2==0]),6)==Rational(1,2)"),
E('Des boules colorées',r"Un sac contient 5 boules rouges, 3 bleues et 2 vertes, indiscernables au toucher. On tire une boule au hasard. Donner les probabilités de rouge et de non-rouge.",r"Le total vaut 10. $P(R)=5/10=\res{1/2}$ et $P(\text{non }R)=1-1/2=\res{1/2}$. Trois couleurs ne signifient pas trois issues équiprobables.","Compter les boules plutôt que les couleurs.","assert Rational(5,10)==1-Rational(5,10)==Rational(1,2)"),
E('Impossible ou certain',r"Sur un dé classique, donner les probabilités d’obtenir 9 et d’obtenir moins de 7.",r"Obtenir 9 est impossible : probabilité $\res0$. Toutes les faces sont inférieures à 7 : probabilité $\res1$.","Comparer l’événement à toutes les issues.","assert all(a<7 for a in range(1,7)) and 9 not in range(1,7)"),
E('Une fréquence expérimentale',r"On obtient 46 fois face au cours de 100 lancers d’une pièce. Donner la fréquence de face. Est-ce une preuve que la pièce est déséquilibrée ?",r"La fréquence est $46/100=\res{0{,}46}$. Cet écart à 0,5 peut se produire avec une pièce équilibrée ; ce seul résultat n’est pas une preuve. La fréquence dépend de l’expérience réalisée.","Ne pas confondre résultat observé et modèle.","assert Rational(46,100)==Rational('.46')"),
E('Une roue à secteurs égaux',r"Une roue a huit secteurs de même angle numérotés de 1 à 8 ; tous ont la même chance d’arrêt. Quelle est la probabilité d’un multiple de 3 ?",r"Les numéros favorables sont 3 et 6 : $2/8=\res{1/4}$. L’égalité des angles et l’hypothèse du modèle justifient le comptage.","Identifier les secteurs équiprobables.","assert [a for a in range(1,9) if a%3==0]==[3,6]"),
E('Deux pièces',r"Deux pièces équilibrées sont lancées indépendamment. Compléter la liste des quatre issues et calculer la probabilité d’exactement une face F.",r"Les issues sont PP, PF, FP, FF. Chacune vaut $1/2\times1/2=1/4$. PF et FP conviennent, d’où $\res{1/2}$. L’ordre distingue les deux issues.","Suivre toutes les feuilles de l’arbre.","assert Rational(1,2)**2*2==Rational(1,2)",figure='proba-pieces'),
E('La somme de deux dés',r"Deux dés équilibrés sont lancés indépendamment. Utiliser le tableau des sommes pour calculer la probabilité d’une somme égale à 7.",r"Les 36 couples ordonnés sont équiprobables. Les six couples $(1;6),(2;5),(3;4),(4;3),(5;2),(6;1)$ conviennent : $\res{1/6}$. Les sommes elles-mêmes ne sont pas équiprobables.","Compter des couples et non des sommes.","assert sum(a+b==7 for a in range(1,7) for b in range(1,7))==6",figure='proba-des'),
E('Avec remise',r"Un sac contient 3 boules rouges et 2 bleues. On tire, on remet la boule, puis on tire de nouveau au hasard. Calculer la probabilité de deux rouges.",r"La composition reste identique : le chemin RR a pour poids $3/5\times3/5=\res{9/25}$. La remise maintient cinq boules à la seconde étape.","Tenir compte de la remise avant la deuxième branche.","assert Rational(3,5)**2==Rational(9,25)",figure='proba-remise'),
E('Sans remise',r"Dans le même sac de 3 rouges et 2 bleues, on tire deux boules successivement sans remise. Calculer la probabilité de deux rouges.",r"Après une rouge, il reste 2 rouges sur 4 boules. La probabilité de RR vaut $3/5\times2/4=\res{3/10}$. Elle est différente du cas avec remise.","Actualiser la composition après la première boule.","assert Rational(3,5)*Rational(2,4)==Rational(3,10)",figure='proba-sans-remise'),
E('Au moins un six',r"Deux dés équilibrés sont lancés indépendamment. Calculer la probabilité d’obtenir au moins un six.",r"L’événement contraire est « aucun six », de probabilité $5/6\times5/6=25/36$. La probabilité cherchée vaut $1-25/36=\res{11/36}$. Additionner $1/6+1/6$ aurait compté deux fois le couple $(6;6)$.","Passer au contraire pour éviter un double comptage.","assert 1-Rational(5,6)**2==Rational(11,36)"),
E('Deux couleurs différentes',r"Reprendre le tirage sans remise de l’exercice 9. Calculer la probabilité d’obtenir deux couleurs différentes.",r"Les chemins RB et BR sont incompatibles. Leurs poids valent $3/5\times2/4=3/10$ et $2/5\times3/4=3/10$. La somme est $\res{3/5}$. Les deux ordres comptent.","Additionner les deux chemins favorables.","assert Rational(3,5)*Rational(2,4)+Rational(2,5)*Rational(3,4)==Rational(3,5)",figure='proba-sans-remise'),
E('Un jeu à points',r"On paie 2 points pour lancer un dé équilibré. Le 6 rapporte 8 points, le 5 rapporte 4 points, les autres 0. Sur un grand nombre de parties, le gain brut moyen théorique est la somme des gains multipliés par leurs probabilités. Le jeu équilibre-t-il mise et gain moyen ?",r"Le gain brut moyen vaut $8/6+4/6=\res2$ points. Il égale la mise : le bilan net moyen théorique est 0. Cela ne garantit ni un remboursement ni un gain à chaque partie ; un résultat individuel peut être $-2$, 2 ou 6 points nets.","Distinguer gain brut, mise et bilan net.","assert Rational(8,6)+Rational(4,6)==2"),
E('Un effectif inconnu',r"Un sac contient 6 rouges et $b$ bleues seulement. La probabilité de tirer rouge au hasard est $2/5$. Trouver $b$.",r"On écrit $6/(6+b)=2/5$. Les produits en croix donnent $30=12+2b$, donc $\res{b=9}$. Avec 15 boules, $6/15=2/5$, ce qui confirme le résultat.","Traduire le total avant le produit en croix.","assert solve(30-2*(6+x),x)==[9]"),
E('Un code à deux chiffres',r"Un générateur choisit indépendamment et uniformément deux chiffres parmi 0, 1, 2, 3, avec répétition possible. Un code peut commencer par 0. Quelle est la probabilité que ses deux chiffres soient distincts ?",r"Il y a $4\times4=16$ codes équiprobables. Pour chaque premier chiffre, trois seconds sont différents : $4\times3=12$. La probabilité vaut $12/16=\res{3/4}$. Le complément correspond à 00, 11, 22, 33.","Préciser si répétition et zéro initial sont autorisés.","assert sum(a!=b for a in range(4) for b in range(4))==12"),
E('Estimer sans promettre',r"Une simulation d’un événement de probabilité $1/3$ donne 327 succès en 1000 essais, puis 3354 en 10000 essais. Comparer les écarts entre fréquences et probabilité. Peut-on garantir que tout essai supplémentaire rapproche la fréquence de $1/3$ ?",r"Les fréquences sont 0,327 et 0,3354. Leurs écarts à $1/3$ valent environ 0,00633 et 0,00207. La deuxième est plus proche dans ces données. Aucune amélioration à chaque étape n’est garantie : un prochain succès ou échec peut augmenter l’écart.","Comparer les écarts absolus sans en faire une règle monotone.","assert abs(Rational(327,1000)-Rational(1,3))>abs(Rational(3354,10000)-Rational(1,3))")
],reperes=['Équiprobabilité et événements contraires','Tableaux et arbres à deux étapes','Tirages avec et sans remise','Fréquences et simulations'],deco='probabilites')
